#include "PluginEditor.h"
AngelVocalAIEditor::AngelVocalAIEditor(AngelVocalAIProcessor&x):AudioProcessorEditor(&x),p(x){setSize(520,300);addAndMakeVisible(b);addAndMakeVisible(s);s.setText("ANGEL MODE • Ready",juce::dontSendNotification);b.onClick=[this]{p.startAnalysis();startTimerHz(10);};}
void AngelVocalAIEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(18,18,22));g.setColour(juce::Colours::white);g.setFont(28);g.drawText("ANGEL VOCAL AI",25,25,470,40,juce::Justification::centredLeft);g.setFont(15);g.setColour(juce::Colours::lightgrey);g.drawText("Adaptive Urban / Reggaetón Vocal Processor",25,70,470,25,juce::Justification::centredLeft);g.setColour(juce::Colour(70,70,80));g.fillRoundedRectangle(25,115,470,16,8);g.setColour(juce::Colour(220,70,90));g.fillRoundedRectangle(25,115,470*p.analysisProgress(),16,8);}
void AngelVocalAIEditor::resized(){b.setBounds(145,165,230,55);s.setBounds(25,235,470,30);}
void AngelVocalAIEditor::timerCallback(){repaint();if(p.analysisReady()){s.setText("ANALYSIS COMPLETE • Vocal chain adapted",juce::dontSendNotification);stopTimer();}else s.setText("LISTENING • "+juce::String((int)(p.analysisProgress()*100))+"%",juce::dontSendNotification);}
